import { createDebateCatalog, choice, reply, ignore } from "./kanab-quest-social-debate-builder";
import type { KqSocialProducerNarrative } from "./kanab-quest-social-producer-types";
import type { KqSocialPlatform } from "./kanab-quest-social-types";

const { add, replyBranches, scenarios, narratives } = createDebateCatalog();
type Draft = ReturnType<typeof choice>;
type MoreArc = {
  id: string; platform: KqSocialPlatform; name: string; title: string; body: string;
  opening: Record<string, Draft>; contexts: Record<string, string>;
  firstTitle: string; firstBody: string; sharp: Draft; explain: Draft; firstIgnored: string;
  secondTitle: string; secondBody: string; challenge: Draft; document: Draft; secondIgnored: string;
  consequences: Record<"sharp" | "explain" | "ignore", string>;
};

/** One publication, then two independent comments beneath that same publication. */
function addArc(arc: MoreArc) {
  const openingId = `${arc.id}-post`, responseId = `${arc.id}-reply`;
  const common = { requirement: "general" as const, arc: arc.name,
    audience: "Des habitués, des collègues et des gens qui découvrent ton compte", character: "Ton compte de producteur CBD" };
  add(openingId, arc.platform, 1, { ...common, title: arc.title, body: arc.body,
    image: "workshop", choices: arc.opening });
  add(responseId, arc.platform, 2, { ...common, title: arc.firstTitle, body: arc.firstBody,
    image: "workshop", replyTo: { scenarioId: openingId, commentIndex: 0 },
    choices: { sharp: arc.sharp, explain: arc.explain, ignore: ignore(arc.firstIgnored) },
    continuations: replyBranches(openingId, arc.contexts) }, openingId);
  const leads = {
    sharp: "J’ai répondu assez sèchement plus haut. Je prends aussi le temps de répondre à ton commentaire.",
    explain: "J’ai développé mon point de vue dans l’autre réponse. Ta question ajoute quelque chose :",
    ignore: "Je n’ai pas répondu à l’autre commentaire. Je te réponds sur ce point :",
  };
  const continuations: NonNullable<KqSocialProducerNarrative["continuations"]> = Object.fromEntries(
    Object.entries(arc.consequences).map(([previous, body]) => [previous, { body,
      choices: {
        challenge: { post: `${leads[previous as keyof typeof leads]}\n\n${arc.challenge.post}` },
        document: { post: `${leads[previous as keyof typeof leads]}\n\n${arc.document.post}` },
      },
    }]),
  );
  add(`${arc.id}-after`, arc.platform, 3, { ...common, title: arc.secondTitle, body: arc.secondBody,
    image: "community", replyTo: { scenarioId: openingId, commentIndex: 1 },
    choices: { challenge: arc.challenge, document: arc.document, refocus: ignore(arc.secondIgnored) },
    continuations }, responseId);
}

addArc({
  id: "ig-debate-filter", platform: "instagram", name: "Une plante dans la mauvaise case",
  title: "Une photo botanique n’est pas toujours une offre",
  body: "Tu veux parler des contresens possibles quand un contenu sur le chanvre est modéré sans son contexte. Défendre une image de travail n’oblige pas à prétendre que tous les vendeurs sont irréprochables. Tu choisis comment poser ce problème.",
  opening: {
    detail: choice("Demander qu’on lise le contexte", "Tu distingues un sujet botanique d’un appel à acheter.", "craft", "Un contenu sur le chanvre peut raconter du travail, expliquer une plante ou chercher à vendre. Ce n’est pas interchangeable. Si une photo de culture est prise pour une offre, je veux pouvoir expliquer son contexte. Pas obtenir un passe-droit parce que je suis producteur.", "Sami demande où passe cette distinction. Lou veut savoir comment elle peut la reconnaître en tant que lectrice.", ["sam", "Oui enfin, une boutique peut très bien appeler sa pub « pédagogie »."], ["visitor", "Moi, comment je distingue le récit de métier du post qui essaie de me vendre quelque chose ?"]),
    frank: choice("Râler contre les raccourcis", "Tu défends une lecture qui dépasse la silhouette d’une feuille.", "reach", "Si on voit une feuille et qu’on a déjà tout décidé sur le message, autant remplacer la lecture par un tampon. Je veux pouvoir parler de chanvre sans que le contexte parte à la poubelle. Une image ne raconte pas à elle seule ce que son auteur propose.", "Le tampon fait rire les habitués. Sami rappelle que le vocabulaire du métier peut aussi servir un discours commercial.", ["sam", "Et le vendeur qui habille sa pub en journal de culture, on doit lui faire confiance sur parole ?"], ["visitor", "Le contexte compte, mais qu’est-ce que je regarde pour reconnaître une intention commerciale ?"]),
    short: choice("Poser une demande limitée", "Tu demandes une explication lisible quand le contexte pose problème.", "care", "Ma demande est assez simple : pouvoir comprendre ce qui pose problème dans un contenu sur le chanvre, et expliquer ce qu’il raconte. Ça ne rend pas toutes les publications acceptables. Ça évite seulement de discuter à coups de suppositions.", "La demande reste mesurée. Sami s’interroge sur ce qu’un vendeur peut cacher derrière une explication bien présentée.", ["sam", "Tout le monde aura une bonne explication pour dire que son post n’est pas une pub."], ["visitor", "Je voudrais surtout des indices pour comprendre quand le compte me raconte son métier et quand il me sollicite."]),
  },
  contexts: { detail: "Sami relève une limite réelle : se dire pédagogique ne suffit pas à décrire ce qu’on fait.", frank: "Ta formule sur le tampon a marqué le ton. Sami revient à la possibilité de déguiser un message commercial.", short: "Sami n’accuse pas un post précis d’avoir enfreint une règle. Il conteste l’efficacité de ta demande." },
  firstTitle: "« La pub habillée en pédagogie »", firstBody: "Sami doute de la frontière que tu proposes. Tu peux discuter de ce risque ou laisser son objection en place.",
  sharp: reply("Refuser le soupçon automatique", "Tu contredis son raccourci avec une pointe d’agacement.", "reach", "Si toute explication est déjà une excuse dans ta tête, on a terminé avant de commencer. Regarde ce que le message fait demander aux gens. On peut critiquer une pub déguisée sans transformer chaque phrase de producteur en pièce à conviction.", "Sami trouve le fond défendable mais le ton inutilement sec. La discussion attire aussi ceux qui veulent opposer vendeurs et lecteurs.", ["sam", "Je parle d’un risque réel, pas de mettre tous les producteurs au tribunal."], ["ines", "On pourrait garder la question sans se distribuer les rôles du méchant."]),
  explain: reply("Reconnaître la frontière difficile", "Tu proposes d’examiner le message plutôt que son étiquette.", "craft", "Oui, appeler un post pédagogique ne prouve rien. Je regarderais ce qu’il affirme, ce qu’il montre et ce qu’il demande au lecteur : comprendre, s’abonner, acheter ? Il peut mélanger plusieurs intentions. C’est précisément pour ça que je demande de lire le contexte.", "Sami conserve sa réserve mais trouve un terrain de discussion. Lou peut reprendre ces questions sans devoir connaître une règle de plateforme.", ["sam", "Là, on examine le contenu au lieu de croire l’étiquette choisie par le vendeur."], ["visitor", "Ce qu’on me demande de faire, c’est déjà un repère que je peux regarder."]),
  firstIgnored: "Tu ne réponds pas à Sami. Son objection reste visible, avec les autres commentaires sous ton post.",
  secondTitle: "Lou cherche des repères", secondBody: "Lou demandait comment lire un compte qui raconte un métier tout en ayant une activité commerciale. Sa question est toujours sous le post d’origine.",
  challenge: reply("Refuser la fausse innocence", "Tu assumes que le compte d’un producteur peut aussi servir son activité.", "reach", "Je ne vais pas te vendre le conte du compte totalement désintéressé. Montrer mon travail peut donner envie de s’y intéresser, évidemment. Ce qui me gêne, c’est de cacher une sollicitation derrière une prétendue conversation innocente. Tu as le droit de regarder ce qu’on attend de toi.", "Lou apprécie la franchise. La formule sur les conversations innocentes relance quelques procès d’intention dans le fil.", ["visitor", "C’est plus honnête que de me dire qu’un compte de producteur n’a jamais d’intérêt commercial."], ["sam", "D’accord, sans décider pour autant que toutes les conversations sont des pièges."]),
  document: reply("Donner trois questions de lecture", "Tu lui proposes des repères sans les faire passer pour une règle officielle.", "craft", "Tu peux te demander : qu’est-ce qui est montré, qu’est-ce qui est affirmé, et qu’est-ce qu’on m’invite à faire ? Ce sont des repères de lecture, pas un règlement. Un récit peut intéresser quelqu’un à mon activité ; une offre, elle, doit pouvoir se reconnaître comme une offre.", "Lou repart avec des questions utilisables. Personne n’a prétendu connaître une décision réelle de modération sur ton compte.", ["visitor", "Je peux lire le message avec ça, sans attendre qu’on me dise quoi penser."], ["jade", "Et le producteur reste responsable de la clarté de ce qu’il propose."]),
  secondIgnored: "Tu laisses la question de Lou sans réponse. Le fil reste consultable et tu n’ajoutes aucun nouveau message en ton nom.",
  consequences: { sharp: "Ta réponse sèche à Sami a déplacé une partie du fil vers ton ton. Lou attend toujours des repères, sans avoir pris part à l’accrochage.", explain: "Tu as proposé à Sami de regarder les intentions du message. Lou posait justement la question du côté des lecteurs ; tu peux lui répondre directement.", ignore: "Tu n’as pas répondu à Sami. Tu peux néanmoins répondre à Lou, ou laisser les deux commentaires sans suite." },
});

addArc({
  id: "ig-debate-gift", platform: "instagram", name: "Payé en visibilité",
  title: "Un petit envoi contre un grand peut-être",
  body: "Tu veux poser tes limites face aux propositions de collaboration fondées sur un produit offert. La visibilité peut avoir un intérêt ; elle ne paie pas automatiquement le travail. Tu n’as pas besoin de conclure un accord pour discuter de ce que tu accepterais.",
  opening: {
    detail: choice("Demander un projet précis", "Tu veux comprendre la proposition avant de parler d’un envoi.", "craft", "« On collabore ? » peut vouloir dire beaucoup de choses. Avant de parler d’un produit offert, j’aimerais savoir quel contenu est proposé, à qui il s’adresse et ce que chacun prend en charge. Je ne confonds pas une idée de collaboration et un colis déjà promis.", "Lou se propose pour un échange de visibilité. Mila rappelle que préparer un contenu demande aussi du travail.", ["visitor", "Tu m’envoies un petit quelque chose et je parle de toi. On verra bien ce que ça donne, non ?"], ["mila", "Tu comptes comment le travail du créateur ? Lui aussi peut passer du temps sans garantie de résultat."]),
    frank: choice("Piquer la monnaie visibilité", "Tu te moques d’une promesse qui fait disparaître le travail.", "reach", "La visibilité, cette monnaie avec laquelle personne ne règle ses factures mais tout le monde veut régler celles du producteur. Je peux écouter un projet. « Envoie toujours, on verra » n’est pas encore un projet.", "La formule circule chez les indépendants. Lou défend l’idée d’essayer sans dossier ; Mila trouve le reproche un peu large.", ["visitor", "Tu compliques tout. Un petit envoi, une story, et peut-être de nouveaux clients : ça peut profiter aux deux."], ["mila", "Le créateur aussi bosse. Attention à ne pas le réduire à quelqu’un qui réclame un cadeau."]),
    short: choice("Dire que les cadeaux se choisissent", "Tu gardes une limite simple sans attaquer les créateurs.", "care", "Offrir quelque chose peut me faire plaisir. Ça reste un choix, pas une case obligatoire dès qu’on me propose une story. Si on veut travailler ensemble, parlons d’abord de ce qu’on veut faire.", "Les habitués comprennent la limite. Lou insiste sur la simplicité d’un essai et Mila soulève l’autre côté de l’échange.", ["visitor", "Justement, on pourrait commencer par un petit envoi sans se prendre la tête."], ["mila", "Et si un créateur te présente une vraie idée, tu reconnais aussi la valeur de son temps ?"]),
  },
  contexts: { detail: "Lou propose d’essayer avant de préciser ce qu’elle ferait. Tu peux décliner sans annoncer un refus de toutes les collaborations.", frank: "Lou répond à ta pique par une promesse de bénéfice possible. Aucun envoi ni résultat n’a été convenu.", short: "Lou insiste, sans avoir apporté de projet plus précis. Ta limite n’a pas disparu parce que la demande semble petite." },
  firstTitle: "« Envoie, on verra bien »", firstBody: "Lou te propose un essai vague. Tu peux lui répondre franchement ou ne pas donner suite. Pour l’instant, vous n’avez convenu de rien.",
  sharp: reply("Refuser le colis à l’aveugle", "Tu renvoies la demande à son manque de contenu.", "reach", "Le « petit quelque chose », c’est du travail pour quelqu’un. Le « on verra », c’est surtout une garantie de ne rien garantir. Si ton idée tient uniquement sur ce que j’envoie, elle a encore besoin de boulot.", "Lou trouve la réponse dure. Des producteurs applaudissent ; d’autres lecteurs auraient préféré une limite sans la pique finale.", ["visitor", "Tu pouvais juste dire non, pas me parler comme si je cherchais à t’arnaquer."], ["noe", "Le non est clair. La dernière phrase va surtout nourrir les réponses."]),
  explain: reply("Poser ce qu’il manque", "Tu demandes du concret sans promettre de rémunération ni de produit.", "craft", "Je peux écouter une idée sans dire oui à un envoi. Quel sujet, quel format, quel public, et quelles attentes de chaque côté ? Je ne demande pas une promesse de ventes. Je veux savoir à quoi on s’engagerait avant de décider.", "Lou comprend ce qu’il faudrait préciser, sans recevoir d’accord. La proposition peut rester une proposition.", ["visitor", "D’accord, je vois la différence entre proposer un contenu et demander d’abord un produit."], ["mila", "Ne pas promettre des ventes impossibles à garantir, c’est déjà une bonne base."]),
  firstIgnored: "Tu ne donnes pas suite à la proposition de Lou. Aucun colis, accord ou rémunération n’est créé ; sa demande reste visible.",
  secondTitle: "Le temps de Mila compte aussi", secondBody: "Mila te demandait de regarder le travail des deux côtés. Elle ne demande pas que tu acceptes la proposition de Lou.",
  challenge: reply("Refuser la compétition des factures", "Tu défends la valeur des deux métiers sans cadeau obligatoire.", "reach", "Oui, son temps compte. Le mien aussi. On n’est pas obligés de faire un concours de factures pour le reconnaître. Ce que je refuse, c’est qu’un métier serve d’argument pour rendre gratuitement le travail de l’autre disponible.", "Mila reconnaît la limite. Le ton ferme ramène aussi ceux qui veulent désigner lequel des deux métiers travaille vraiment.", ["mila", "Reconnaître les deux valeurs, c’est exactement mon point."], ["sam", "Alors ne laissons pas le fil repartir en concours du métier le plus légitime."]),
  document: reply("Reconnaître les deux contributions", "Tu fais de la discussion un accord possible, pas une dette.", "craft", "Oui. Une photo, une vidéo, une écriture, ça se prépare. Une collaboration devrait permettre de nommer ces contributions, ce que chacun peut proposer et ce qu’il préfère refuser. Reconnaître ce travail ne m’oblige pas à accepter chaque projet, pas plus que le créateur ne me doit une publication.", "Mila peut être d’accord sans faire semblant qu’un contrat existe. Le fil laisse de la place au refus des deux côtés.", ["mila", "Voilà : une discussion entre deux personnes qui peuvent aussi dire non."], ["ines", "Ça évite de présenter le cadeau comme un paiement magique qui arrange forcément tout le monde."]),
  secondIgnored: "Tu laisses le commentaire de Mila sans réponse. Son point sur le travail créatif reste visible dans le fil.",
  consequences: { sharp: "Tu as refusé sèchement la demande de Lou. Mila pose une autre question : la valeur du travail créatif, même quand tu déclines un projet.", explain: "Tu as demandé à Lou de préciser une proposition. Mila veut savoir si cette discussion reconnaîtrait aussi le temps du créateur.", ignore: "Tu n’as pas répondu à Lou. Tu peux répondre au point de Mila sans ouvrir de négociation ni promettre un envoi." },
});

addArc({
  id: "ig-debate-workbench", platform: "instagram", name: "Une étagère n’est pas un stock disponible",
  title: "Tout ce qui passe à l’image n’est pas à commander",
  body: "Tu réfléchis à la façon de montrer l’organisation d’un atelier sans donner une fausse impression de quantité disponible. Des contenants, des étiquettes et des outils racontent du travail ; les lecteurs peuvent pourtant y voir une annonce commerciale.",
  opening: {
    detail: choice("Séparer atelier et disponibilité", "Tu expliques ce qu’un décor ne permet pas de conclure.", "craft", "Des bocaux sur une étagère ne disent pas à eux seuls ce qui est disponible. Ils ne donnent ni quantité, ni état d’un lot, ni date de vente. Je veux pouvoir montrer le travail autour du produit sans transformer chaque contenant visible en promesse de commande.", "Max y voit une manière de jouer sur les apparences. Inès cherche surtout où trouver une information de disponibilité explicite.", ["skeptic", "Pratique : on montre plein de bocaux pour faire sérieux, puis faut surtout pas demander ce qu’il y a dedans."], ["ines", "Du coup, comment je sais qu’un post annonce vraiment quelque chose de disponible ?"]),
    frank: choice("Se moquer du catalogue imaginaire", "Tu refuses que le décor soit lu comme un inventaire.", "reach", "Une étagère dans le cadre, et voilà qu’on lui colle un catalogue, un stock et un délai de livraison. Le bocal n’a même pas eu besoin de parler. Je préfère dire clairement ce que je présente plutôt que laisser le décor faire de grandes promesses à ma place.", "Le bocal muet amuse. Max accuse les producteurs d’entretenir eux-mêmes cette lecture ; Inès demande un repère concret.", ["skeptic", "Vous savez très bien que les bocaux font vendeur. Faut pas jouer les surpris après."], ["ines", "Alors qu’est-ce que je dois lire pour distinguer une vue de l’atelier d’une vraie disponibilité ?"]),
    short: choice("Poser une légende honnête", "Tu gardes une limite facile à comprendre.", "care", "Je veux montrer mon métier sans faire dire trop de choses à une photo. Une vue d’atelier reste une vue d’atelier. Si je parle d’une disponibilité, je dois le dire explicitement et avec les bonnes informations.", "Le message rassure certains lecteurs. Max soupçonne une séparation commode entre l’image et ce qu’elle suggère.", ["skeptic", "Une image attire les clients, puis la petite phrase explique qu’elle ne promet rien. Facile."], ["ines", "Une annonce explicite, ça me va. Je ne veux pas devoir deviner si je peux demander un produit."]),
  },
  contexts: { detail: "Max te prête une intention de gonfler l’activité. Le post ne lui donne pourtant aucun inventaire à vérifier.", frank: "Max soulève ce que le décor peut suggérer. Tu peux reconnaître cette lecture sans inventer le contenu des bocaux.", short: "Max met l’image et la légende en tension. La question est leur clarté, pas une quantité de stock connue du fil." },
  firstTitle: "Le décor ferait-il le travail du vendeur ?", firstBody: "Max conteste l’impression que peuvent donner les images d’atelier. Il n’a désigné aucun lot dont tu pourrais confirmer la disponibilité ici.",
  sharp: reply("Refuser son inventaire à distance", "Tu lui renvoies ce qu’il a déduit d’un décor.", "reach", "Tu viens de compter un stock avec tes suppositions et tu me demandes de le défendre. Une image peut être mal légendée, oui. Ça ne transforme pas ce qu’on imagine derrière chaque bocal en fait établi.", "Max s’accroche au ton. Le fil parle davantage de ses suppositions que de la manière d’annoncer une disponibilité.", ["skeptic", "Toujours le lecteur qui comprend mal, jamais le vendeur qui entretient le flou."], ["sam", "On peut admettre l’ambiguïté d’une image sans inventer un inventaire."]),
  explain: reply("Reconnaître l’effet du décor", "Tu prends la clarté du message à ta charge.", "craft", "Oui, une image peut suggérer plus que ce qu’elle montre. C’est aussi au compte qui la publie de préciser son sujet. Je ne te demande pas de deviner les quantités : je dis justement qu’une annonce de disponibilité demande autre chose qu’une étagère dans le cadre.", "Max garde sa méfiance, mais Inès voit que la clarification ne repose pas seulement sur le lecteur.", ["ines", "Merci de ne pas me demander d’enquêter sur les bocaux pour comprendre le post."], ["skeptic", "Très bien. Il faudra surtout que la légende soit aussi claire que cette réponse."]),
  firstIgnored: "Tu ne réponds pas à Max. Son interprétation reste visible, avec ton post et les autres commentaires.",
  secondTitle: "Inès veut savoir quoi lire", secondBody: "Inès n’a pas demandé un inventaire secret. Elle voulait reconnaître une annonce explicite, sans transformer chaque photo en demande de commande.",
  challenge: reply("Refuser le jeu de devinettes", "Tu défends une information simple avec un ton piquant.", "reach", "Tu ne devrais pas devoir résoudre une énigme entre trois bocaux et un emoji. Si je propose quelque chose, je dois l’écrire clairement. Le suspense sert à raconter une histoire ; pour savoir ce qui est disponible, il devient vite pénible.", "Inès apprécie la franchise. Des lecteurs reprennent surtout la pique contre les annonces trop vagues.", ["ines", "C’est exactement ça : je préfère une information lisible à une chasse aux indices."], ["noe", "Et on peut garder une jolie image sans lui confier tout le service client."]),
  document: reply("Distinguer les deux messages", "Tu lui donnes un critère sans annoncer de stock.", "craft", "Une annonce doit nommer ce qui est proposé et donner les informations de disponibilité au moment où elle paraît. Un récit d’atelier peut simplement raconter un geste ou une organisation. Ce post parle de cette différence ; il n’annonce ni quantité ni lot disponible.", "Inès comprend le rôle des deux formats. Tu n’as pas transformé une explication du compte en offre de vente.", ["ines", "Compris. Je peux suivre les coulisses sans prendre chaque image pour une ouverture de commandes."], ["jade", "Et quand l’information change, l’annonce concernée doit rester compréhensible."]),
  secondIgnored: "Tu laisses la question d’Inès sans réponse. Ton post reste visible ; chacun peut relire ce que tu y expliquais.",
  consequences: { sharp: "Tu as contesté les déductions de Max. Inès attendait un repère pratique et n’a pas demandé à arbitrer votre ton.", explain: "Tu as reconnu qu’une image peut suggérer trop de choses. Le commentaire d’Inès permet de dire ce qu’une annonce devrait rendre explicite.", ignore: "Tu n’as pas répondu à Max. Inès a posé une question distincte ; tu peux lui répondre sans confirmer l’inventaire imaginé par Max." },
});

addArc({
  id: "ig-debate-privacy", platform: "instagram", name: "Un désaccord ne donne pas une adresse",
  title: "Les captures qui rendent un client reconnaissable",
  body: "Tu veux parler de ces disputes commerciales racontées avec des captures d’écran. On peut expliquer un désaccord sans livrer une personne au public. Tu choisis comment défendre cette limite, sans prétendre qu’un litige de ta boutique vient d’avoir lieu.",
  opening: {
    detail: choice("Défendre la vie privée", "Tu sépares l’explication d’un litige de l’exposition d’une personne.", "craft", "Si je raconte un désaccord commercial, montrer un nom, une adresse ou une référence de commande n’aide pas à comprendre le fond. Je veux pouvoir expliquer ma position sans transformer les abonnés en équipe chargée de retrouver la personne.", "Max réclame au contraire une exposition publique des clients qu’il juge abusifs. Sami se demande comment un professionnel peut alors montrer sa version.", ["skeptic", "Les gens qui font les malins, faut afficher leur nom. Ça leur apprendrait."], ["sam", "Mais comment un commerçant se défend sans qu’on lui demande de croire sa version sur parole ?"]),
    frank: choice("Refuser le tribunal avec coordonnées", "Tu attaques l’idée de punir quelqu’un par les abonnés.", "reach", "Une dispute avec un client n’est pas un bon prétexte pour offrir ses coordonnées au fil. On peut être furieux sans monter une chasse. Le courage de répondre ne se mesure pas au nombre d’inconnus qu’on envoie sur quelqu’un.", "Le ton attire des soutiens et des objections. Max présente l’exposition comme une sanction méritée ; Sami garde une question sur les preuves.", ["skeptic", "Quand quelqu’un te pourrit, tu le protèges encore ? Le nom, et chacun juge."], ["sam", "Je comprends la limite. Mais montrer une version vérifiable, ça reste possible comment ?"]),
    short: choice("Garder les personnes hors du spectacle", "Tu poses une limite sans ouvrir un dossier fictif.", "care", "Je peux parler d’un problème sans rendre quelqu’un identifiable. Les noms et les coordonnées ne sont pas un bonus de divertissement pour les abonnés. Un désaccord peut rester un désaccord, même quand il énerve.", "Le post est bref. Max veut faire de l’exposition un avertissement ; Sami distingue la confidentialité du droit de répondre.", ["skeptic", "Trop gentil. Si personne n’est jamais affiché, certains se croient tout permis."], ["sam", "Une personne mise en cause peut quand même vouloir expliquer ce qui s’est passé, non ?"]),
  },
  contexts: { detail: "Max veut une punition publique, pas une explication du désaccord.", frank: "Max demande de laisser la foule juger une personne identifiable. Ton post critiquait précisément ce mécanisme.", short: "Max confond ta limite sur les coordonnées avec l’absence de toute réponse possible." },
  firstTitle: "« Balance le nom »", firstBody: "Max réclame l’identité de personnes qu’il juge abusives. Tu peux refuser sa logique sans publier la moindre information privée.",
  sharp: reply("Lui refuser son spectacle", "Tu réponds franchement à l’envie d’exposition.", "reach", "Tu veux une explication ou un nom à faire circuler ? Parce que ce n’est pas le même boulot. Mes abonnés ne sont pas une brigade de représailles. Si ça manque de spectacle à ton goût, tu vas être déçu.", "Max parle de naïveté et quelques lecteurs saluent la fermeté. La limite tient, avec une tension supplémentaire autour du ton.", ["skeptic", "Fais le gentil, tu verras comment les gens en profitent."], ["ines", "Je peux m’intéresser au problème sans avoir besoin de savoir où quelqu’un habite."]),
  explain: reply("Distinguer répondre et exposer", "Tu refuses l’identification sans nier qu’un problème peut être traité.", "craft", "Refuser de donner un nom n’empêche pas de répondre, de conserver les éléments utiles ou de traiter un problème par le bon canal. Ce qui n’aide pas, c’est de permettre à des inconnus d’aller chercher la personne. Tu ne sais pas ce qu’ils feront ensuite.", "Sami reconnaît que la confidentialité ne signifie pas l’inaction. Max reste favorable à l’exposition ; tu ne lui fournis rien pour la mener.", ["sam", "D’accord : garder des éléments ne veut pas dire les donner au fil."], ["skeptic", "Moi je trouve toujours qu’un nom calmerait certains. On ne sera pas d’accord."]),
  firstIgnored: "Tu ne réponds pas à Max et tu ne publies aucune donnée personnelle. Sa demande reste visible, sans recevoir les informations qu’elle réclame.",
  secondTitle: "Sami demande comment répondre sur le fond", secondBody: "Sami soulève une vraie difficulté : une personne mise en cause veut parfois montrer sa version. Il ne demande pas de publier des coordonnées.",
  challenge: reply("Refuser le faux choix", "Tu contredis l’opposition entre tout montrer et se taire.", "reach", "Heureusement qu’il reste des possibilités entre « croyez-moi aveuglément » et « voilà ses coordonnées ». On peut exposer le point contesté, expliquer ce qu’on sait et ce qui manque. La curiosité du fil ne lui donne pas un droit sur tout le dossier.", "Sami accepte la distinction. La formule peut aussi sembler repousser des questions pourtant légitimes.", ["sam", "Je ne demandais pas tout le dossier. Je voulais justement savoir comment discuter du point contesté."], ["jade", "La limite gagne à rester précise, sinon elle ressemble vite à un refus de répondre à tout."]),
  document: reply("Expliquer sans rendre identifiable", "Tu décris une démarche prudente, sans simuler un litige résolu.", "craft", "On peut décrire le désaccord et ses limites, sans détails qui permettraient de retrouver quelqu’un. Une capture mal masquée peut encore être reconnaissable. Et tout n’a pas à être arbitré publiquement : les éléments nécessaires peuvent rester dans l’échange concerné.", "Sami voit mieux ce qui peut être expliqué au public. Aucun échange privé réel ni dossier client n’a été inventé pour illustrer ton point.", ["sam", "Je comprends : montrer sa position n’oblige pas à faire voter les abonnés sur une personne."], ["ines", "Le prénom masqué ne suffit pas toujours si tout le reste permet de reconnaître quelqu’un."]),
  secondIgnored: "Tu laisses la question de Sami sans réponse. Les échanges restent centrés sur la vie privée, sans désigner de client.",
  consequences: { sharp: "Tu as refusé sèchement le spectacle demandé par Max. Sami avait posé une question distincte sur la possibilité de répondre avec des éléments.", explain: "Tu as expliqué à Max pourquoi le traitement d’un problème ne passe pas par l’exposition. Sami attend des repères sur ce qu’on peut raconter.", ignore: "Tu n’as pas répondu à Max ni divulgué de coordonnées. Tu peux répondre à Sami sur le principe, sans ouvrir de dossier imaginaire." },
});

addArc({
  id: "ig-debate-credit", platform: "instagram", name: "Qui a fait l’image ?",
  title: "Le producteur au centre, les autres hors champ",
  body: "Tu veux parler de la place des personnes qui aident un compte à raconter son travail. Être le sujet d’une image ne signifie pas l’avoir faite seul. Le post pose tes principes pour une éventuelle collaboration, sans annoncer de séance photo déjà réalisée.",
  opening: {
    detail: choice("Nommer les contributions", "Tu défends un crédit précis plutôt qu’un merci vague.", "craft", "Quand un contenu se construit à plusieurs, j’aime savoir qui a fait quoi : image, montage, texte, idée. Le producteur peut être au centre du cadre sans avoir tout fabriqué autour. Un crédit précis raconte mieux ce travail qu’un petit « merci à l’équipe » perdu en bas.", "Max ramène la visibilité à celui qui figure sur l’image. Mila rappelle qu’un crédit ne règle pas toutes les questions d’utilisation.", ["skeptic", "Les gens viennent voir le producteur, pas le générique de fin de chaque photo."], ["mila", "Et être créditée ne veut pas dire que j’autorise toutes les réutilisations. On en parle quand ?"]),
    frank: choice("Piquer les héros qui font tout seuls", "Tu attaques le récit du compte fabriqué sans personne autour.", "reach", "Le héros qui cultive, photographie, monte, écrit et invente tout, ça fait une belle légende. Quand d’autres ont bossé, leur nom n’est pas un défaut dans le récit. On peut être fier de son métier sans avaler celui des voisins.", "La formule plaît aux créateurs. Max trouve le sujet accessoire ; Mila veut dépasser le simple affichage d’un nom.", ["skeptic", "On va bientôt devoir lire trois signatures pour regarder un bocal. Personne ne demande ça."], ["mila", "Mon nom, oui. Mais il faut aussi convenir de ce qu’on pourra faire de l’image ensuite."]),
    short: choice("Garder une signature honnête", "Tu fais de l’attribution une habitude possible.", "care", "Si quelqu’un m’aide à faire un contenu, je veux nommer sa contribution. Ça n’enlève rien au travail que je raconte. Ça évite juste de laisser croire que tout ce qui apparaît sur mon compte est sorti de mes seules mains.", "Le principe est simple. Max lui oppose l’impatience supposée des lecteurs ; Mila distingue reconnaissance et autorisation.", ["skeptic", "Vous compliquez un post qui devrait juste montrer le boulot. Les gens s’en fichent des crédits."], ["mila", "Ça me va sur le principe. Et les usages prévus, on les définit avant que le contenu parte partout ?"]),
  },
  contexts: { detail: "Max juge le crédit inutile parce que le producteur reste le sujet du compte.", frank: "Ta formule sur le héros a fait réagir Max. Il parle au nom des lecteurs sans savoir ce que chacun souhaite voir.", short: "Max confond une mention claire avec un long générique imposé au public." },
  firstTitle: "« Personne ne lit les crédits »", firstBody: "Max voudrait faire disparaître les contributions de l’image au nom de la simplicité. Tu peux répondre ou laisser sa remarque sans suite.",
  sharp: reply("Refuser l’effacement pratique", "Tu lui renvoies la facilité d’oublier le travail des autres.", "reach", "Ce qui est pratique, c’est surtout de garder le résultat et de faire disparaître les gens derrière. Un nom et un rôle ne vont pas te confisquer ta journée. Le bouton pour passer au post suivant fonctionne toujours.", "Max trouve la réponse méprisante. Les personnes sensibles au travail créatif apprécient la limite, sans toutes aimer la manière.", ["skeptic", "Sympa l’accueil. Il faut applaudir ton générique ou dégager, c’est ça ?"], ["mila", "Tu peux défendre le crédit sans donner l’impression de virer ceux qui ne le lisent pas."]),
  explain: reply("Relier le nom au travail", "Tu défends une information courte et utile.", "craft", "Tu n’es pas obligé de t’intéresser à chaque rôle. Mais une mention permet à ceux qui le veulent de savoir qui a fait l’image ou le montage. Elle évite aussi de m’attribuer un travail que je n’ai pas fait. Ça peut tenir en une ligne lisible.", "Max n’y trouve toujours pas d’intérêt personnel. Les autres lecteurs comprennent pourquoi cette information peut avoir sa place sans devenir le sujet entier du post.", ["ines", "Une ligne suffit pour comprendre que le compte n’a pas tout fait seul."], ["skeptic", "Bon, une ligne. Tant qu’on n’en fait pas la moitié de la légende."]),
  firstIgnored: "Tu ne réponds pas à Max. Le principe annoncé reste visible ; aucun crédit réel ni collaboration passée n’est ajouté à ton compte.",
  secondTitle: "Mila distingue crédit et accord", secondBody: "Mila veut parler des usages d’un contenu réalisé à plusieurs. Elle n’a pas accepté une collaboration par le simple fait de commenter.",
  challenge: reply("Refuser le merci qui achète tout", "Tu contestes l’idée qu’une mention remplace une discussion.", "reach", "Bien sûr qu’il faut en parler avant. « Je t’ai taguée » n’est pas une baguette magique qui transforme une image en réserve utilisable pour n’importe quoi. Si le projet change, on remet la question sur la table au lieu de compter sur un merci pour tout régler.", "Mila retrouve sa préoccupation. La formule attire aussi des lecteurs qui ramènent leurs propres disputes, sans que tu puisses les trancher.", ["mila", "Oui : je veux savoir ce qu’on prévoit, pas le découvrir après un recadrage."], ["sam", "Et les cas racontés dans les réponses auront chacun leur contexte."]),
  document: reply("Parler des usages avant de publier", "Tu décris les points à convenir, sans affirmer qu’un accord existe.", "craft", "Avant : le contenu prévu, où il apparaîtrait, comment la contribution serait nommée et ce qui demanderait une nouvelle discussion. On peut être d’accord pour un usage et pas pour tous. Te créditer et convenir des usages sont deux choses à prendre au sérieux.", "Mila voit ce que tu proposerais de discuter. Aucun accord de diffusion ni collaboration fictivement conclue n’est annoncé.", ["mila", "C’est ce que j’attendais : un accord précis, pas un tag qui ferait office de blanc-seing."], ["jade", "Et ça permet de dire non à une réutilisation sans nier le travail fait ensemble."]),
  secondIgnored: "Tu laisses la question de Mila sans réponse. Elle n’a accepté aucun usage et tu n’en annonces aucun à sa place.",
  consequences: { sharp: "Ta réponse à Max défend le crédit mais a durci le ton. Mila posait une question différente sur les usages convenus avant publication.", explain: "Tu as expliqué à Max l’utilité d’une mention. Mila rappelle que cette mention ne suffit pas à définir ce qu’on ferait du contenu.", ignore: "Tu n’as pas répondu à Max. Tu peux répondre à Mila sur un éventuel accord, sans prétendre qu’une collaboration a déjà eu lieu." },
});

addArc({
  id: "x-debate-photo-credit", platform: "x", name: "La photo change de propriétaire dans la légende",
  title: "Recadrer une image jusqu’à faire disparaître son auteur",
  body: "Tu veux poser ta limite face aux reprises de photos de producteurs. Ton sujet est ce qu’une réutilisation peut faire croire sur l’origine de l’image. Tu parles d’une situation possible, sans annoncer un vol découvert ni accuser un compte précis.",
  opening: {
    detail: choice("Défendre le contexte de l’image", "Tu distingues partager une photo et lui inventer une origine.", "craft", "Si une photo de mon travail circule, je veux qu’on puisse retrouver son origine. La reprendre avec une légende qui fait croire qu’elle vient d’un autre atelier, ce n’est plus simplement la partager. L’image finit par raconter une histoire qu’elle n’a pas vécue.", "Max traite toute publication publique comme une invitation à reprendre. Mila demande ce que tu souhaiterais obtenir d’une personne qui réutilise une photo.", ["skeptic", "Tu mets une photo sur Internet et tu découvres qu’elle circule. Fallait la garder dans ton téléphone."], ["mila", "Dans ce cas, tu demanderais un crédit, une correction de légende ou un retrait ? Ce n’est pas la même demande."]),
    frank: choice("Piquer les producteurs de recadrages", "Tu critiques l’identité de façade construite avec les images des autres.", "reach", "Le recadrage qui fait disparaître l’auteur, puis la légende qui fait apparaître un nouveau producteur : joli tour. Pour raconter son propre travail, il reste pourtant une technique assez fiable : commencer par ne pas s’attribuer celui du voisin.", "La formule attire des réactions. Max prétend que tu découvres le fonctionnement du réseau ; Mila veut une demande plus précise qu’un coup de gueule.", ["skeptic", "Bienvenue sur Internet. Si tu ne veux pas qu’on reprenne, tu ne postes pas."], ["mila", "Et concrètement, qu’est-ce que tu demanderais : qu’on te nomme, qu’on corrige ce qui est raconté ou qu’on retire l’image ?"]),
    short: choice("Poser une limite sur l’origine", "Tu gardes le propos centré sur ce que raconte une reprise.", "care", "Partager une photo et faire croire qu’on l’a produite soi-même, je ne mets pas ça dans la même case. Je veux pouvoir montrer mon métier sans voir l’origine de l’image disparaître dans la légende de quelqu’un d’autre.", "La limite paraît claire aux habitués. Max renvoie toute responsabilité à celui qui publie ; Mila distingue les suites possibles.", ["skeptic", "Une fois que c’est public, faut arrêter de vouloir contrôler ce que tout le monde en fait."], ["mila", "Pour une reprise qui pose problème, quelle demande tu ferais en premier ? Un crédit n’arrange pas toujours une légende trompeuse."]),
  },
  contexts: { detail: "Max confond la circulation d’une image et le changement de l’histoire qu’on lui attribue.", frank: "Ton tour de recadrage était une critique générale. Max n’a fourni aucun exemple de photo à examiner.", short: "Max invoque l’impossibilité de tout contrôler. Tu peux poser une limite sans promettre ce contrôle." },
  firstTitle: "« Fallait pas poster »", firstBody: "Max réduit le choix à se taire ou accepter toutes les reprises. Tu peux lui répondre sur cette opposition, sans inventer une image déjà volée.",
  sharp: reply("Refuser son permis de s’approprier", "Tu attaques le raisonnement qui fait du partage un renoncement.", "reach", "C’est pratique : celui qui montre son travail serait naïf, celui qui change son origine serait juste à l’aise avec Internet. Je ne demande pas au monde d’oublier une image. Je refuse qu’on lui invente un autre producteur. La nuance ne demande pas un diplôme.", "Max reprend la dernière phrase et la discussion se crispe. Certains lecteurs retiennent surtout l’opposition entre partager et s’attribuer.", ["skeptic", "Et voilà la petite leçon. Tu maîtriseras quand même pas Internet."], ["jade", "Poser une limite n’est pas promettre qu’on maîtrisera toutes les reprises."]),
  explain: reply("Distinguer circulation et attribution", "Tu expliques ce que tu contestes réellement.", "craft", "Je sais qu’une image peut circuler. Ce que je conteste, c’est de lui attribuer un autre auteur ou une autre production. Je ne peux pas tout contrôler ; ça ne m’empêche pas de demander qu’une reprise raconte correctement d’où elle vient.", "Max maintient que le contrôle sera difficile. Mila voit une demande qu’on peut formuler sans annoncer une victoire imaginaire.", ["skeptic", "Demander, oui. Obtenir que tout le monde le fasse, bonne chance."], ["mila", "La demande reste valable même si on ne promet pas son résultat."]),
  firstIgnored: "Tu ne réponds pas à Max. Sa remarque reste visible ; aucun compte n’est accusé et aucune demande de retrait n’est envoyée.",
  secondTitle: "Mila veut savoir ce que tu demanderais", secondBody: "Mila distingue plusieurs demandes possibles. Elle ne te demande pas de raconter un retrait ou une correction déjà obtenus.",
  challenge: reply("Refuser le crédit qui masque le reste", "Tu refuses de réduire toute la question à un petit nom ajouté.", "reach", "Un crédit minuscule ne remet pas d’aplomb une légende qui raconte une autre histoire. Ce qui compte pour moi, c’est ce qu’on fait croire avec l’image. Si cette histoire est fausse, ajouter mon nom dans un coin ne suffirait pas à me satisfaire.", "Mila reconnaît que l’attribution et le récit vont ensemble. Des lecteurs voudraient une règle unique, que ta réponse ne leur donne pas.", ["mila", "Oui : remettre le nom et remettre le contexte peuvent demander deux corrections différentes."], ["sam", "Il faudrait regarder la reprise concernée avant de choisir la demande."]),
  document: reply("Adapter la demande à la reprise", "Tu précises ton raisonnement sans simuler une démarche accomplie.", "craft", "Je commencerais par regarder ce qui pose problème : auteur effacé, origine changée, usage auquel je ne souhaite pas être associé. La demande pourrait alors être un crédit, une correction ou un retrait. Je ne peux pas choisir honnêtement entre ces réponses sans voir le cas précis.", "Mila comprend ce que tu examinerais. Aucun retrait, accord ou signalement n’est présenté comme déjà réalisé.", ["mila", "C’est plus utile que de demander automatiquement la même chose pour toutes les reprises."], ["ines", "Et ça évite de transformer un exemple possible en accusation contre quelqu’un."]),
  secondIgnored: "Tu laisses la question de Mila sans réponse. Elle ne sait toujours pas ce que tu demanderais en cas de reprise d’une photo.",
  consequences: { sharp: "Tu as vivement contesté le « fallait pas poster » de Max. Mila attend une réponse sur la demande que tu ferais, pas sur sa répartie.", explain: "Tu as distingué la circulation d’une image et son attribution. Mila demande comment cette distinction guiderait ta démarche.", ignore: "Tu n’as pas répondu à Max. Tu peux traiter la question de Mila au conditionnel, sans annoncer un conflit réel avec un autre compte." },
});

addArc({
  id: "x-debate-giveaway", platform: "x", name: "Une communauté de passages obligés",
  title: "Taguer des amis n’est pas forcément s’intéresser au métier",
  body: "Tu veux parler des concours qui remplissent les commentaires de mentions et de partages. Les gens peuvent aimer jouer ; le nombre de participations raconte autre chose que leur intérêt pour ta production. Tu choisis comment exprimer cette réserve.",
  opening: {
    detail: choice("Distinguer participation et intérêt", "Tu questionnes ce qu’un concours permet de mesurer.", "craft", "Un concours peut faire découvrir un compte. Mais un commentaire écrit pour participer ne dit pas forcément qu’on s’intéresse au métier derrière. Je ne veux pas appeler communauté fidèle une série de passages obligés pour tenter de gagner quelque chose.", "Noé défend l’utilité d’un premier contact. Inès aime les concours et ne veut pas être traitée comme une fausse abonnée.", ["noe", "Faut bien que les gens arrivent quelque part. Tu vas pas leur faire passer un entretien de passion avant de jouer."], ["ines", "Moi j’aime participer. Ça fait de moi une mauvaise abonnée ou pas assez sérieuse ?"]),
    frank: choice("Piquer l’usine à mentions", "Tu critiques les chiffres gonflés par des gestes imposés.", "reach", "Tague tes amis, partage, commente, recommence : le fil ressemble parfois à une pointeuse. Après, on présente ça comme une conversation passionnée. Les gens ont joué, très bien. On peut éviter d’inventer une déclaration d’amour au métier derrière chaque mention.", "La pointeuse amuse. Noé trouve que tu dénigres un outil de découverte ; Inès se demande si tu vises aussi les participants.", ["noe", "Tu tapes sur un truc qui peut faire découvrir une petite activité. Tout le monde n’arrive pas avec une passion déjà installée."], ["ines", "J’aime jouer et je peux aussi être curieuse. On doit choisir entre les deux ?"]),
    short: choice("Garder les chiffres à leur place", "Tu refuses d’interpréter toute participation comme un soutien durable.", "care", "Je peux apprécier un concours sans prendre ses commentaires pour une mesure parfaite de confiance. Participer, découvrir un compte et suivre un métier dans la durée, ce sont trois choses qui peuvent se rejoindre. Elles ne sont pas identiques au départ.", "Noé insiste sur le rôle du premier pas. Inès veut être sûre qu’on ne classe pas les lecteurs selon leur manière d’arriver.", ["noe", "Donc on fait quoi, on attend que les curieux tombent du ciel sans leur proposer de jouer ?"], ["ines", "Si j’arrive par un concours, j’ai quand même ma place dans les discussions ensuite ?"]),
  },
  contexts: { detail: "Noé entend une sélection des lecteurs là où tu questionnais l’interprétation des chiffres.", frank: "La pointeuse a donné un ton moqueur au post. Noé défend la possibilité de découvrir une activité par le jeu.", short: "Noé transforme ta réserve sur les chiffres en rejet de tous les concours. Tu peux préciser ou laisser passer." },
  firstTitle: "Noé défend le premier pas", firstBody: "Noé pense qu’un concours peut ouvrir une porte à des gens qui ne connaissaient pas ton métier. C’est une objection, pas une demande de lot à offrir.",
  sharp: reply("Refuser le faux dilemme", "Tu contredis l’idée qu’il faudrait choisir entre concours et invisibilité.", "reach", "On peut proposer un jeu sans faire semblant que chaque mention prouve une passion. Je critique le discours sur les chiffres, pas le droit des curieux de venir. Inutile de me faire jouer le videur du club des producteurs.", "Noé entend la distinction mais trouve la réponse défensive. Le mot « videur » attire plus de réactions que le sujet des mesures.", ["noe", "Tu pouvais dire ça sans te fabriquer un personnage que je n’avais pas demandé."], ["sam", "Le point utile, c’est ce qu’on prétend mesurer avec les participations."]),
  explain: reply("Reconnaître la découverte possible", "Tu gardes le bénéfice du jeu sans lui attribuer un résultat automatique.", "craft", "Oui, ça peut être un premier pas. Je veux seulement distinguer ce qu’on sait : des personnes ont participé. Pour savoir si elles restent, comprennent le métier ou veulent acheter, il faut autre chose que leur commentaire de participation. Le concours peut aider sans tout prouver.", "Noé peut défendre le jeu sans te demander de surinterpréter ses effets. Inès retrouve une place pour sa curiosité.", ["noe", "Présenté comme ça, je te suis : une porte d’entrée, pas un certificat de communauté fidèle."], ["ines", "Et je peux découvrir le métier après être venue jouer."]),
  firstIgnored: "Tu ne réponds pas à Noé. Le désaccord reste visible ; aucun concours, prix à gagner ou engagement de distribution n’est créé.",
  secondTitle: "Inès ne veut pas être classée à l’entrée", secondBody: "Inès demandait si aimer les concours la rendait moins légitime dans la conversation. Sa question porte sur l’accueil des lecteurs.",
  challenge: reply("Refuser le brevet de bonne abonnée", "Tu rejettes une hiérarchie des lecteurs fondée sur leur arrivée.", "reach", "Tu n’as pas à passer un brevet de bonne abonnée. Tu peux venir pour jouer, rester pour une question ou repartir. Ce que je demande au compte, c’est de ne pas inventer tes intentions à partir d’un commentaire. Je ne vais pas te les inventer moi-même.", "Inès apprécie la réponse directe. Le ton mordant fait aussi repartir le débat sur les comptes qui classeraient leur public.", ["ines", "Alors ça me va. Je n’ai pas envie de justifier ma présence sous chaque post."], ["jade", "Accueillir les gens et lire les chiffres avec prudence, ça peut aller ensemble."]),
  document: reply("Lui laisser définir son intérêt", "Tu distingues ta critique des compteurs du jugement sur les personnes.", "craft", "Bien sûr que tu as ta place. Tu peux aimer jouer et t’intéresser au travail, ou seulement aimer jouer. Mon point vise la manière dont un compte interprète les participations. Ça ne me donne pas le droit de te dire pourquoi tu es là ni ce que tu devrais aimer.", "Inès sait qu’elle peut participer sans se présenter comme une passionnée de longue date. Tu n’as pas promis de concours pour conclure l’échange.", ["ines", "Merci. Je peux être curieuse sans devenir un argument dans un bilan de communication."], ["noe", "Et un lecteur de passage peut devenir un habitué sans qu’on l’annonce avant lui."]),
  secondIgnored: "Tu laisses la question d’Inès sans réponse. Tu n’ajoutes aucun message pour lui attribuer une intention ou lui promettre un concours.",
  consequences: { sharp: "Ta réponse à Noé a clarifié le sujet mais conservé un ton combatif. Inès voulait simplement savoir si elle était la bienvenue.", explain: "Tu as reconnu le rôle possible d’un concours. Inès attend une réponse sur sa place personnelle dans les discussions.", ignore: "Tu n’as pas répondu à Noé. Tu peux répondre à Inès sans organiser un concours ni prétendre que l’objection précédente est réglée." },
});

addArc({
  id: "x-debate-headline", platform: "x", name: "Le titre mange le métier",
  title: "Entre plante miracle et menace absolue",
  body: "Tu veux parler des accroches qui résument le chanvre à une promesse spectaculaire ou à une peur. Une phrase peut donner envie de lire sans répondre à toutes les questions. Tu choisis jusqu’où pousser la critique de ces raccourcis.",
  opening: {
    detail: choice("Défendre une accroche fidèle", "Tu veux que le titre garde le sens de ce qui suit.", "craft", "Sur le chanvre, on peut parler du travail, des règles et des difficultés sans chercher une plante miracle ou une menace absolue. Un bon titre donne envie de lire la suite. Il ne devrait pas obliger la suite à réparer ce qu’il a fait croire.", "Sami demande si tu voudrais neutraliser les titres critiques. Lou pose le problème de l’attention dans un fil qui défile vite.", ["sam", "Vous voulez surtout des titres qui vous arrangent. Quand c’est critique, ça devient du sensationnalisme."], ["visitor", "Une accroche trop plate, personne ne s’arrête dessus. Comment tu gardes l’attention sans simplifier ?"]),
    frank: choice("Piquer les deux tiroirs faciles", "Tu te moques du choix entre miracle et catastrophe.", "reach", "Le chanvre dans les titres : soit il va sauver le monde, soit il va le faire s’écrouler. Au milieu, des gens essaient de travailler, de comprendre les règles et de parler clairement. C’est moins commode à ranger dans un gros titre, mais c’est là que le métier existe.", "La caricature des deux tiroirs parle à certains lecteurs. Sami soupçonne une demande de traitement favorable ; Lou défend le besoin d’accrocher.", ["sam", "Le producteur adore la presse quand elle le valorise. Dès qu’elle dérange, elle ne comprend plus rien."], ["visitor", "D’accord sur les excès, mais il faut bien une phrase qui donne envie d’ouvrir."]),
    short: choice("Demander une promesse tenue", "Tu gardes le principe à la taille d’une phrase.", "care", "J’aimerais lire des titres sur le chanvre dont le texte tient la promesse. Une critique peut être ferme. Une question peut intriguer. On n’a pas besoin de faire croire à une certitude que le reste du contenu ne donne pas.", "Le propos attire une objection sur la sensibilité des producteurs à la critique. Lou demande où placer la simplification nécessaire.", ["sam", "La promesse tenue, ça veut souvent dire pas trop de questions qui fâchent les vendeurs."], ["visitor", "Un titre ne peut pas tout contenir. Où tu places la limite entre court et trompeur ?"]),
  },
  contexts: { detail: "Sami soupçonne une demande de titres favorables. Ton post parlait de leur fidélité au contenu.", frank: "Ta caricature était mordante. Sami met en cause les intérêts du producteur plutôt que la qualité d’une accroche précise.", short: "Sami assimile ton exigence de clarté à un refus de questions gênantes." },
  firstTitle: "« Vous voulez une presse qui vous arrange »", firstBody: "Sami te prête une préférence pour les récits flatteurs. Tu peux distinguer une critique documentée d’une accroche qui raconte autre chose.",
  sharp: reply("Refuser le procès de confort", "Tu refuses qu’on déduise ta demande de tes intérêts supposés.", "reach", "Tu peux poser une question qui dérange sans lui inventer la réponse dans le titre. Me faire passer pour un producteur allergique à la critique, ça évite commodément de discuter de ce point. Une accroche flatteuse peut être tout aussi bidon.", "Sami reste méfiant mais doit composer avec ta critique des titres favorables aussi. La formule « bidon » donne un ton plus dur au fil.", ["sam", "Très bien. Il faudra accepter le même examen quand le titre te fait plaisir."], ["jade", "Le critère tient justement s’il s’applique dans les deux sens."]),
  explain: reply("Appliquer le même critère aux éloges", "Tu reconnais qu’une critique peut être justifiée.", "craft", "Une critique étayée peut me déplaire et rester juste. Une accroche flatteuse peut me profiter et être trompeuse. Je demande la même chose aux deux : que la phrase n’affirme pas davantage que ce que le contenu permet de comprendre.", "Sami garde son exigence de questions gênantes. Lou peut revenir au travail de formulation plutôt qu’à tes intentions supposées.", ["sam", "Si tu gardes ce critère pour les compliments aussi, la demande est plus crédible."], ["visitor", "Ça laisse de la place à un titre fort sans lui demander de mentir pour accrocher."]),
  firstIgnored: "Tu ne réponds pas à Sami. Son soupçon reste visible ; aucun média ni article précis n’est accusé d’avoir publié une fausse information.",
  secondTitle: "Lou veut une phrase qui donne envie", secondBody: "Lou n’a pas demandé de tout dire dans le titre. Elle cherche la frontière entre une accroche courte et une promesse trompeuse.",
  challenge: reply("Refuser le spectaculaire obligatoire", "Tu défends une tension réelle plutôt qu’une certitude fabriquée.", "reach", "Le métier a déjà de quoi accrocher : du temps, des choix, des règles qui pèsent et des désaccords. Si la seule idée qui arrête le lecteur est une promesse qu’on doit défaire ensuite, c’est peut-être l’idée qu’il faut retravailler, pas la réalité.", "Lou trouve le défi intéressant, même s’il ne résout pas chaque problème d’écriture. Les habitués proposent leurs propres formules.", ["visitor", "Je vois : trouver la tension du sujet au lieu d’en inventer une plus grosse."], ["noe", "Et accepter qu’une bonne phrase ne fasse pas forcément exploser le compteur."]),
  document: reply("Garder l’essentiel de la nuance", "Tu expliques la différence entre choisir un angle et changer le sens.", "craft", "Un titre choisit forcément un angle. La limite, pour moi, c’est quand il change le sens : présenter une question comme résolue, une possibilité comme certaine, un exemple comme la règle. On peut être court et laisser visible ce qui reste une question.", "Lou dispose d’un critère de relecture. Tu n’as annoncé ni résultat scientifique ni actualité juridique pour fabriquer un exemple accrocheur.", ["visitor", "Oui, on peut raccourcir sans changer le degré de certitude."], ["sam", "Et cette exigence vaut aussi pour les posts du producteur, pas seulement pour la presse."]),
  secondIgnored: "Tu laisses la question de Lou sans réponse. Elle reste visible sous ton post, parmi les remarques sur les titres accrocheurs.",
  consequences: { sharp: "Tu as vivement répondu au soupçon de Sami. Lou attend toujours un repère pour écrire court sans trahir le sujet.", explain: "Tu as appliqué le même critère aux titres critiques et flatteurs. Lou demande comment le traduire dans une phrase courte.", ignore: "Tu n’as pas répondu à Sami. Tu peux répondre à Lou sur l’écriture sans prétendre avoir convaincu le premier commentateur." },
});

addArc({
  id: "x-debate-correction", platform: "x", name: "Changer d’avis sans effacer les traces",
  title: "Une bonne explication ne convainc pas forcément",
  body: "Tu réexamines une idée de communication : croire qu’une explication assez claire ferait forcément disparaître le désaccord. Tu veux dire ce qui change dans ta façon d’aborder les échanges, sans inventer un ancien post ni un incident passé.",
  opening: {
    detail: choice("Reconnaître une idée trop simple", "Tu distingues comprendre une explication et lui donner raison.", "craft", "J’avais tendance à croire qu’une bonne explication finirait forcément par mettre les gens d’accord. Je revois ça. On peut comprendre ce que je dis et ne pas partager mon avis. Expliquer le métier reste utile ; obtenir l’accord de tout le fil n’est pas une mesure sérieuse de réussite.", "Max y voit un changement opportuniste. Jade soulève un autre sujet : la trace à laisser quand on corrige une publication réelle.", ["skeptic", "Pratique de changer de discours dès que le premier marche pas."], ["jade", "Et quand on change vraiment une affirmation publiée, comment les lecteurs voient la correction ?"]),
    frank: choice("Ranger l’envie d’avoir raison partout", "Tu prends l’ancien réflexe avec autodérision.", "reach", "Je range une idée encombrante : croire qu’en expliquant un peu mieux, j’aurais enfin le dernier mot. Les gens peuvent avoir compris et continuer à ne pas être d’accord. Le téléphone ne délivre pas de diplôme d’unanimité, même quand on s’acharne.", "Le diplôme d’unanimité amuse. Max soupçonne une manière de rebaptiser un échec ; Jade parle de corrections qu’on devrait pouvoir retrouver.", ["skeptic", "Donc quand tu convaincs pas, tu annonces que convaincre n’était pas le but. Bien joué."], ["jade", "Revoir son avis, oui. Mais si ça concerne un vrai post erroné, il faut que la correction reste visible."]),
    short: choice("Dire simplement ce qui change", "Tu poses une limite à l’objectif de convaincre.", "care", "Je veux continuer à expliquer mon travail, en acceptant qu’on puisse comprendre et ne pas être d’accord. Je ne veux plus faire de chaque réponse un examen à réussir devant tout le fil. C’est un changement dans mon intention, pas une promesse de rester toujours calme.", "Les habitués accueillent cette limite. Max soupçonne une pirouette ; Jade distingue une évolution d’avis d’une correction factuelle.", ["skeptic", "La porte de sortie parfaite quand la discussion ne tourne pas comme tu veux."], ["jade", "Changer d’intention et corriger une information fausse, c’est différent. Comment tu traiterais le second cas ?"]),
  },
  contexts: { detail: "Max te prête un motif opportuniste. Ton post portait sur une idée que tu réexamines, pas sur une publication effacée.", frank: "Max interprète l’autodérision comme une esquive. Tu peux préciser ta limite sans te fabriquer une ancienne victoire ou défaite.", short: "Max soupçonne une sortie commode. Rien dans le fil n’établit qu’une ancienne information aurait été corrigée ou supprimée." },
  firstTitle: "« Tu changes quand ça t’arrange »", firstBody: "Max met en cause les raisons du changement. Tu peux lui répondre sans lui demander de te croire irréprochable.",
  sharp: reply("Refuser l’immobilité comme preuve", "Tu te moques du choix entre ne rien revoir et être accusé.", "reach", "Si je ne change jamais, je suis borné. Si je revois une idée, c’est une combine. Ton système a l’avantage de ne jamais risquer de te contredire. Je préfère expliquer ce que je change que jouer ce petit championnat.", "Max s’accroche à la pique. Des lecteurs apprécient la réplique, d’autres trouvent qu’elle ressemble au réflexe que tu voulais justement calmer.", ["skeptic", "Pour quelqu’un qui lâche le dernier mot, tu le défends encore très bien."], ["ines", "La limite annoncée peut être sincère même si la première réponse pique encore."]),
  explain: reply("Nommer précisément le changement", "Tu limites ta promesse à ce que tu peux vraiment dire.", "craft", "Ce que je change, c’est l’idée qu’expliquer devrait forcément produire un accord. Je ne dis pas que toutes mes réponses seront parfaites, ni qu’un désaccord m’évitera de corriger une erreur. Tu peux juger ce que j’écris ensuite sans me prêter d’avance un résultat.", "Max garde ses réserves. Jade retrouve la distinction entre accepter un désaccord et reconnaître une information à corriger.", ["skeptic", "On verra à la prochaine contradiction, alors."], ["jade", "Oui : un désaccord n’oblige pas à changer de fait, une erreur demande autre chose."]),
  firstIgnored: "Tu ne réponds pas à Max. Le changement d’intention reste formulé dans ton post ; aucun ancien message n’est retouché ou effacé.",
  secondTitle: "Jade parle des vraies corrections", secondBody: "Jade demande ce qui devrait se passer si une information publiée se révélait fausse. Elle ne prétend pas qu’une telle erreur vient d’être trouvée ici.",
  challenge: reply("Refuser la correction invisible", "Tu défends une trace claire quand le sens d’un message change.", "reach", "Corriger discrètement puis regarder les lecteurs comme s’ils avaient rêvé l’ancienne phrase, ça ne m’intéresse pas. Si une information importante change, je veux que ce changement soit compréhensible. Sinon on gagne un post plus propre et on perd le fil de ce qu’on a raconté.", "Jade approuve la trace visible. Le ton peut entraîner des accusations générales contre des comptes dont personne n’a examiné les corrections.", ["jade", "Oui, les lecteurs qui ont vu la première version doivent pouvoir comprendre la différence."], ["sam", "Ça reste un principe ; on n’a pas un compte précis à accuser ici."]),
  document: reply("Décrire une correction qu’on peut suivre", "Tu distingues opinion révisée et fait à rectifier.", "craft", "Pour une information fausse, je voudrais dire ce qui était erroné, ce qui la corrige et où le retrouver. Pour une opinion qui évolue, expliquer ce qui me fait la revoir. Ce n’est pas la même chose. Ici, je parle d’une intention ; je n’annonce pas la correction d’un ancien post.", "Jade voit la différence entre les deux démarches. Le fil ne fabrique pas d’erreur passée pour justifier la discussion.", ["jade", "C’est clair : une intention évolue, un fait erroné demande une rectification identifiable."], ["visitor", "Et je n’ai pas à chercher une ancienne publication qui n’a jamais été citée."]),
  secondIgnored: "Tu ne réponds pas à Jade. Sa question sur la trace d’une correction reste ouverte sous ton post.",
  consequences: { sharp: "Ta répartie à Max a gardé un ton combatif. Jade pose une question distincte sur la trace d’une correction factuelle.", explain: "Tu as nommé le changement d’intention sans le confondre avec une correction. Jade veut savoir ce que tu ferais dans ce second cas.", ignore: "Tu n’as pas répondu à Max. Tu peux répondre à Jade sur une éventuelle correction, sans réécrire un passé qui n’a pas été établi." },
});

addArc({
  id: "x-debate-petition", platform: "x", name: "Une signature n’est pas un mandat général",
  title: "Relayer une demande sans parler à la place du coin",
  body: "Tu veux discuter de la façon de soutenir une demande collective autour du métier. Relayer une pétition, partager une préoccupation et représenter les chanvriers du secteur ne sont pas la même chose. Aucun groupe ne t’a donné mandat dans cette histoire.",
  opening: {
    detail: choice("Lire la demande avant le mot d’ordre", "Tu veux savoir ce qu’un soutien signifie concrètement.", "craft", "Avant de relayer une pétition sur le métier, je veux lire ce qu’elle demande, à qui et au nom de qui. Partager une difficulté ne signifie pas signer chaque phrase du texte. Et mon compte ne devient pas la voix de tous les chanvriers du coin parce que j’appuie sur partager.", "Noé craint que ces réserves paralysent toute action. Jade pose la question de ceux qui veulent contribuer sans afficher leur nom.", ["noe", "À force de tout discuter, personne ne bouge. Il faut aussi savoir soutenir quand quelqu’un se lance."], ["jade", "Et ceux qui partagent la demande mais ne veulent pas afficher leur nom publiquement, on les laisse où ?"]),
    frank: choice("Refuser le nous qui grossit tout seul", "Tu critiques l’unanimité annoncée par un seul compte.", "reach", "« Tous les producteurs du secteur demandent… » : parfois, le « tous » a l’air de pousser plus vite que les signatures. Je peux soutenir une demande en mon nom. Je ne vais pas distribuer la voix des voisins pour donner plus de poids à ma phrase.", "La formule fait réagir. Noé y voit une façon de décourager ceux qui prennent l’initiative ; Jade rappelle les soutiens qui ne passent pas par un nom affiché.", ["noe", "Facile de chipoter sur les mots pendant que d’autres essaient de mobiliser."], ["jade", "Le soutien discret existe aussi. Si quelqu’un ne veut pas être nommé, ça ne veut pas dire qu’il s’en fiche."]),
    short: choice("Garder ta signature à sa place", "Tu peux soutenir un point sans t’inventer un collectif derrière.", "care", "Je peux défendre une demande qui me paraît juste et expliquer pourquoi. Je parle alors en mon nom. Les autres producteurs décideront eux-mêmes s’ils veulent la soutenir, la discuter ou ne pas s’y associer.", "Noé appelle à un soutien plus spontané. Jade demande comment laisser une place aux personnes réticentes à s’exposer.", ["noe", "On a besoin de gens qui relaient, pas seulement de gens qui prennent leurs distances."], ["jade", "On peut aussi aider sans vouloir que son nom circule avec le texte, non ?"]),
  },
  contexts: { detail: "Noé défend le besoin d’agir. Tu peux reconnaître cette urgence sans annoncer de pétition déjà signée.", frank: "Ta pique sur le « tous » a agacé Noé. Il te demande de soutenir l’initiative, pas de prouver un mandat qui n’existe pas.", short: "Noé interprète la limite de ta parole comme une prise de distance. Le fil ne contient pourtant aucune adhésion à comptabiliser." },
  firstTitle: "« Il faut arrêter de discuter et soutenir »", firstBody: "Noé voudrait que les producteurs relaient plus facilement une demande collective. Tu peux lui répondre sans annoncer une signature ou un engagement à sa place.",
  sharp: reply("Refuser la signature sous pression", "Tu défends le droit de lire sans recevoir une leçon de solidarité.", "reach", "Lire ce qu’on soutient, ce n’est pas saboter ceux qui se bougent. Si la seule façon d’aider, c’est de ne pas poser de question, le collectif commence avec un drôle de règlement. Ma signature n’est pas un bouton qu’on presse à ma place.", "Noé trouve le reproche excessif. La réplique plaît aux lecteurs qui se sont déjà sentis poussés à afficher un soutien.", ["noe", "Je parle d’entraide, pas de te forcer la main. Tu charges un peu."], ["ines", "On peut encourager à regarder une demande sans exiger un accord immédiat."]),
  explain: reply("Soutenir l’initiative sans tout approuver", "Tu reconnais l’effort de mobilisation tout en gardant le choix du texte.", "craft", "Je comprends qu’une initiative ait besoin de relais. Je peux reconnaître ce travail et vouloir comprendre la demande avant de m’y associer. Un soutien précis est plus solide qu’un partage fait pour éviter de passer pour le mauvais voisin. Ça laisse aussi la possibilité de proposer une modification.", "Noé reste pressé mais reconnaît l’intérêt d’un soutien qui tient sur le fond. Jade peut revenir à la place des personnes discrètes.", ["noe", "D’accord, tant que la discussion sert à avancer et pas à repousser indéfiniment."], ["jade", "Un accord sur une demande précise peut aussi rassurer ceux qui hésitent à s’exposer."]),
  firstIgnored: "Tu ne réponds pas à Noé. Aucune pétition n’est signée, relayée ou déposée ; ton silence ne vaut pas mandat collectif.",
  secondTitle: "Jade défend les soutiens discrets", secondBody: "Jade demandait si une personne pouvait partager une préoccupation sans voir son nom circuler. Elle ne t’a pas autorisé à compter son soutien.",
  challenge: reply("Refuser le tableau d’honneur des soutiens", "Tu critiques le tri entre les noms visibles et les autres.", "reach", "Je ne veux pas d’un tableau des bons voisins d’un côté et des suspects silencieux de l’autre. Chacun a ses raisons de s’exposer ou non. On peut proposer de participer ; on ne transforme pas les absents d’une liste en adversaires du métier.", "Jade apprécie la limite. Le ton tranché peut donner l’impression de viser ceux qui organisent, même lorsqu’ils n’imposent rien.", ["jade", "Oui. Ne pas afficher son nom ne suffit pas à savoir ce que quelqu’un pense."], ["noe", "Et une liste peut servir à montrer des soutiens volontaires sans juger ceux qui n’y sont pas."]),
  document: reply("Laisser choisir la forme de participation", "Tu distingues intérêt, contribution et signature publique.", "craft", "Oui, on peut proposer plusieurs façons de contribuer et demander clairement ce qui sera public. Une discussion, une aide ou un intérêt ne sont pas automatiquement une signature. Et je ne compterais personne parmi les soutiens sans son accord sur ce qu’on lui fait soutenir.", "Jade voit une place possible pour une participation discrète. Aucun nom ni soutien n’est ajouté à une liste au cours de cet échange.", ["jade", "C’est la distinction que je cherchais. Une conversation ne doit pas se retrouver transformée en adhésion."], ["ines", "Savoir à l’avance ce qui sera rendu public aide aussi à décider librement."]),
  secondIgnored: "Tu laisses la question de Jade sans réponse. Son hésitation à s’exposer reste visible, sans que tu l’encourages ou la contestes.",
  consequences: { sharp: "Tu as vivement refusé la pression ressentie dans le commentaire de Noé. Jade posait une autre question sur la place de ceux qui ne veulent pas être nommés.", explain: "Tu as reconnu le besoin de relais tout en gardant un soutien précis. Jade demande quelles formes de participation laisser aux personnes discrètes.", ignore: "Tu n’as pas répondu à Noé. Tu peux répondre à Jade sans relayer de pétition, recueillir de signature ou parler au nom du quartier." },
});

export const KQ_SOCIAL_COMMUNITY_MORE_DEBATE_SCENARIOS = scenarios;
